public class METPickingListRegistrationStatusUpdateJob extends RunBaseBatch implements BatchRetryable
{
    Integer dummy;


    QueryRun       queryRun;
    boolean         calledFromForm;

    #define.CurrentVersion(1)
    #localmacro.CurrentList
        dummy
    #endmacro

}

Method.Source:
public Object dialog()
{
    DialogRunbase       dialog = super();
    ;

    return dialog;
}

public void initQuery()
{
    Query                   query = new Query();
    QueryBuildDataSource    wmsPickingRouteQbds = query.addDataSource(tablenum(WMSPickingRoute));
    QueryBuildRange         qBR;
    ;

    qBR = SysQuery::findOrCreateRange(wmsPickingRouteQbds, fieldnum(WMSPickingRoute, expeditionStatus));
    qBR.value(queryValue(WMSExpeditionStatus::Started));
    qBR.status(RangeStatus::Locked);

    queryRun = new QueryRun(query);
}

public boolean unpack(container _packedClass)
{
    Version    version = RunBase::getVersion(_packedClass);
    container  queryCon;
    switch (version)
    {
        case #CurrentVersion:
            [version, #CurrentList, queryCon] = _packedClass;
            if (SysQuery::isPackedOk(queryCon))
            {
                queryRun = new QueryRun(queryCon);
            }
            else
            {
                this.initQuery();
            }
            break;
        default:
            return false;
    }
    return true;
}

public void setSelectedRouteRange(Args _args, FormRun _callerForm)
{
    Set                     recIdSet = new Set(Types::Int64);
    SetEnumerator           setEnumerator;
    Common                  selectedCommon;
    FormDataSource          wmsPickingRouteDS;
    QueryBuildDataSource    qbds;
    str                     rangeValue;

    if (_callerForm)
    {
        wmsPickingRouteDS = _callerForm.dataSource(tablestr(WMSPickingRoute));
    }

    if (wmsPickingRouteDS)
    {
        selectedCommon = wmsPickingRouteDS.getFirst(true);
        while (selectedCommon)
        {
            if (selectedCommon.RecId)
            {
                recIdSet.add(selectedCommon.RecId);
            }
            selectedCommon = wmsPickingRouteDS.getNext();
        }
    }

    if (recIdSet.elements() == 0 && _args.record() && _args.record().TableId == tablenum(WMSPickingRoute))
    {
        recIdSet.add(_args.record().RecId);
    }

    if (recIdSet.elements() == 0)
    {
        return;
    }

    setEnumerator = recIdSet.getEnumerator();
    while (setEnumerator.moveNext())
    {
        if (rangeValue)
        {
            rangeValue += ',';
        }
        rangeValue += int642str(setEnumerator.current());
    }

    qbds = queryRun.query().dataSourceTable(tablenum(WMSPickingRoute));
    SysQuery::findOrCreateRange(qbds, fieldnum(WMSPickingRoute, RecId)).value(rangeValue);
}

public void run()
{
    int                     processedCounter;
    int                     failedCounter;
    WMSPickingRoute         wmsPickingRoute;

    while (queryRun.next())
    {
        wmsPickingRoute = queryRun.get(tablenum(WMSPickingRoute));

        try
        {
            ttsBegin;
            wmsPickingRoute.selectForUpdate(true);
            wmsPickingRoute.checkFinishRoute();
            ttsCommit;

            processedCounter++;
        }
        catch (Exception::Error)
        {
            if (appl.ttsLevel() > 0)
            {
                ttsAbort;
            }
            failedCounter++;
            error(strFmt("@MET:METPicklistRouteProcessError", wmsPickingRoute.PickingRouteID));
        }
        catch (Exception::Deadlock)
        {
            if (appl.ttsLevel() > 0)
            {
                ttsAbort;
            }
            failedCounter++;
            error(strFmt("@MET:METPicklistRouteProcessDeadlock", wmsPickingRoute.PickingRouteID));
        }
        catch (Exception::UpdateConflict)
        {
            if (appl.ttsLevel() > 0)
            {
                ttsAbort;
            }
            failedCounter++;
            error(strFmt("@MET:METPicklistRouteProcessUpdateConflict", wmsPickingRoute.PickingRouteID));
        }
        catch (Exception::CLRError)
        {
            if (appl.ttsLevel() > 0)
            {
                ttsAbort;
            }
            failedCounter++;
            error(strFmt("@MET:METPicklistRouteProcessCLRError", wmsPickingRoute.PickingRouteID));
        }
    }

    info(strFmt("@MET:METPicklistRouteProcessSummary", processedCounter, failedCounter));
}

public static METPickingListRegistrationStatusUpdateJob construct()
{
    return new METPickingListRegistrationStatusUpdateJob();
}

static ClassDescription description()
{
    return "Update the activation status of picking list registration header and lines";
}

public static void main(Args _args)
{
    METPickingListRegistrationStatusUpdateJob    runObject = METPickingListRegistrationStatusUpdateJob::construct();
    FormRun                                       callerForm;
    FormDataSource                                wmsPickingRouteDS;
    ;
    if (_args
        && _args.dataset() == tablenum(WMSPickingRoute)
        && _args.record())
    {
        callerForm = _args.caller();

        if (callerForm)
        {
            wmsPickingRouteDS = callerForm.dataSource(tablestr(WMSPickingRoute));
        }

        if (wmsPickingRouteDS)
        {
            wmsPickingRouteDS.research(true);
        }

        runObject.calledFromForm = true;
        runObject.initQuery();
        runObject.setSelectedRouteRange(_args, callerForm);
        runObject.run();

        if (wmsPickingRouteDS)
        {
            wmsPickingRouteDS.research(true);
        }
    }
    else
    {
        if (runObject.prompt())
        {
            runObject.runOperation();
        }
    }
}
